// ── SCE Accepted Subset §2.15: what a host observes of a sce-static machine ──

/// The published variables (`sce:direction="out"`) as one owned value, in
/// declaration order.
#[derive(Debug, Clone, PartialEq)]
#[allow(non_snake_case)]
pub struct SheetPeerData {
    pub node: u64,
    pub hub: bool,
    pub clock: SheetPeerHlcRecord,
    pub cells: Vec<SheetPeerLwwCellRecord>,
    pub rows: Vec<SheetPeerRgaNodeRecord>,
    pub gone: Vec<SheetPeerRgaGoneRecord>,
    pub cols: Vec<SheetPeerRgaNodeRecord>,
    pub gone_cols: Vec<SheetPeerRgaGoneRecord>,
    pub shown: Vec<SheetPeerShownRecord>,
    pub lamport: u64,
    pub orphans: u32,
    pub refusals: u32,
}

/// What a host observes: the full active configuration — every active state,
/// each region of a `<parallel>` included — and the published variables,
/// taken together between two host calls, which is a macrostep boundary (W3C
/// SCXML Appendix D). `truncated` is `true` when that macrostep was stopped at
/// the microstep ceiling, so the configuration is not a stable one. Owned: a
/// host holding one keeps what it saw whatever the machine does next.
#[derive(Debug, Clone, PartialEq)]
pub struct SheetPeerSnapshot {
    pub configuration: SheetPeerConfiguration,
    pub data: SheetPeerData,
    pub truncated: bool,
}

/// The snapshot of a running machine, as an extension of the runtime's
/// `Engine` (a foreign type, so a local trait — the `Inject` shape).
pub trait SheetPeerObserve {
    /// The machine as the host sees it now: one [`SheetPeerSnapshot`],
    /// never a state between two microsteps.
    fn snapshot(&self) -> SheetPeerSnapshot;
}

impl SheetPeerObserve for Engine<SheetPeerPolicy> {
    fn snapshot(&self) -> SheetPeerSnapshot {
        let policy = self.policy();
        SheetPeerSnapshot {
            configuration: self.get_active_states(),
            data: SheetPeerData {
                node: policy.node,
                hub: policy.hub,
                clock: policy.clock,
                cells: policy.cells.clone(),
                rows: policy.rows.clone(),
                gone: policy.gone.clone(),
                cols: policy.cols.clone(),
                gone_cols: policy.gone_cols.clone(),
                shown: policy.shown.clone(),
                lamport: policy.lamport,
                orphans: policy.orphans,
                refusals: policy.refusals,
            },
            truncated: self.last_macrostep_truncated(),
        }
    }
}

